insert into public.marketing_resources
  (slug, title, description, category, read_minutes, related_href, related_label, sections, is_published, sort_order)
values
('home-blood-pressure-monitoring', 'How to measure your blood pressure at home, properly', 'The five mistakes that quietly inflate a home reading, and how to build a measurement habit your doctor can actually trust.', 'Blood pressure', 4, '/hypertension', 'Hypertension care at Tarragon', '[{"heading":"Why a home reading is often more useful than a clinic one","paragraphs":["Many people''s blood pressure runs higher in a clinic simply from the nerves of being there, a well-known effect called white-coat hypertension. A series of calm, correctly-taken home readings over days or weeks usually paints a truer picture than a single clinic visit, which is why doctors increasingly ask patients to bring in their own log."]},{"heading":"Five mistakes that quietly inflate a reading","paragraphs":["Talking or scrolling your phone during the measurement, a full bladder, an unsupported arm (let it rest at heart height on a table, not held up in the air), a cuff over clothing rather than bare skin, and taking it right after coffee, a cigarette, or a rushed walk in the door can each add several points to the number, enough to change what a reading means."]},{"heading":"A simple routine that removes the guesswork","paragraphs":["Sit quietly for five minutes first. Feet flat on the floor, back supported, arm resting at heart height. Take two readings, one minute apart, and record both rather than only the lower one. Do this at roughly the same time each day, morning and evening if your doctor has asked for that, for at least a week before any decision is made from the pattern."]},{"heading":"What to do with the numbers","paragraphs":["A log of real readings, dated, is far more useful to a doctor than a verbal ''it''s usually fine.'' If your home average sits at 135/85 or higher, or any single reading is well above 180/120, that is worth a call rather than waiting for your next scheduled appointment."]}]'::jsonb, true, 11),
('blood-pressure-medication-myths', 'Why you shouldn''t stop your blood pressure medicine when you feel fine', 'The quiet reason so many people stop treatment early, and why hypertension has no symptom that tells you it''s back.', 'Blood pressure', 4, '/hypertension', 'Hypertension care at Tarragon', '[{"heading":"The trap: feeling fine means nothing","paragraphs":["Hypertension is sometimes called a silent condition for a reason: it produces essentially no symptoms until it has already caused damage. A person whose pressure has been brought under control by medication feels exactly the same as a person whose pressure is quietly climbing again. Feeling fine is not feedback; only a reading is."]},{"heading":"Why people stop anyway","paragraphs":["The most common reasons are almost never medical: running out and delaying a refill, a busy week that breaks the routine, hearing a rumour that the medicine ''damages the kidneys'' or is only meant to be short-term, or simply feeling well enough to assume it''s no longer needed. None of these are safe reasons to stop without telling a doctor first."]},{"heading":"What actually happens when you stop","paragraphs":["For most blood pressure medicines, pressure rises back toward its untreated level within days to a couple of weeks, quietly, with no warning sign. The risk of stroke and heart attack rises with it. If a medicine genuinely isn''t suiting you, side effects, cost, or difficulty remembering doses, that is a real reason to change the plan, but the answer is a different medicine or a different routine, not silence."]},{"heading":"If cost or access is the real reason","paragraphs":["Tell your doctor. There is almost always a cheaper, equally effective alternative on the market, and a doctor who knows the real reason can actually solve it, switch drugs, simplify the dosing schedule, connect you with a pharmacy that delivers, rather than a plan quietly falling apart in silence."]}]'::jsonb, true, 12),
('why-crash-diets-dont-work', 'Why crash diets don''t work, and what actually keeps weight off', 'The biology behind the rebound, and the unglamorous approach that actually holds weight loss for good.', 'Weight', 5, '/obesity', 'The Tarragon weight programme', '[{"heading":"The rebound is not a willpower failure","paragraphs":["When weight drops very fast, your body reads it as a threat, not a goal. Hunger hormones rise, metabolism slows slightly to conserve energy, and the drive to eat becomes genuinely stronger, not weaker. Most people who lose weight quickly on a crash diet regain it within a year, and this is a predictable biological response, not a personal failing."]},{"heading":"What ''crash'' actually means","paragraphs":["Very low-calorie plans, skipping meals for days, tea and juice ''cleanses,'' and waist trainers all share the same flaw: they are not something a person can live on for more than a few weeks, so whatever weight comes off returns the moment normal eating resumes, often with a little extra alongside it."]},{"heading":"What holds weight off instead","paragraphs":["Slower, smaller, sustained changes: a modest and genuinely livable calorie reduction, more protein and fibre so meals stay filling, regular movement, and enough sleep, since poor sleep measurably increases hunger and cravings the next day. A rate of half a kilogram to a kilogram a week is realistic and far more likely to still be true a year from now."]},{"heading":"Track the trend, not the day","paragraphs":["Weight moves several kilograms up and down within a single week from water, salt, and hormones alone, so a bad number on a Tuesday means very little. Weighing at a consistent time and watching the weeks-long trend, not any single reading, is what keeps people from abandoning a plan that is actually working."]}]'::jsonb, true, 55),
('exercise-for-weight-loss-how-much', 'Exercise for weight loss: how much do you actually need?', 'Why exercise alone rarely moves the scale much, and what it''s actually the best tool in existence for.', 'Weight', 4, '/obesity', 'The Tarragon weight programme', '[{"heading":"The uncomfortable truth about exercise and the scale","paragraphs":["A 30-minute brisk walk burns roughly what a small bottle of soft drink contains in calories. Exercise alone, without any change to eating, moves the scale far less than most people expect, and appetite often quietly rises to compensate. This is not a reason to skip it; it''s a reason to be honest about what it''s for."]},{"heading":"What exercise is genuinely the best tool for","paragraphs":["Keeping weight off once it''s lost, protecting muscle while you lose fat (so the weight that comes off is fat, not muscle), and lowering blood pressure, blood sugar and cardiovascular risk largely independent of what happens to your weight at all. People who exercise regularly keep weight off far better than people who rely on diet changes alone."]},{"heading":"How much is actually enough","paragraphs":["Roughly 150 minutes a week of brisk walking or similar activity, about 20-25 minutes most days, is the widely-used benchmark for general health. For weight maintenance specifically, some evidence points toward needing closer to 250-300 minutes a week. Either way, consistency across months matters far more than intensity on any single day."]},{"heading":"It doesn''t need a gym","paragraphs":["Brisk walking, stairs instead of a lift, dancing, carrying shopping, an okada-free commute twice a week, all count. The best form of exercise is the one you''ll actually keep doing in six months; a modest routine you sustain beats an ambitious one you abandon after a fortnight."]}]'::jsonb, true, 58),
('cancer-screening-by-age', 'Cancer screening by age: what to book, and when', 'The screenings worth booking at each life stage, matched to age and sex, and why early detection changes everything about treatment.', 'Screening', 5, '/prevention', 'Preventive care at Tarragon', '[{"heading":"Why the timing matters, not just the test","paragraphs":["Cancer screening exists to catch disease before it causes symptoms, when treatment is simplest and most effective. Screening too early wastes money on a low-risk population; screening too late misses the window it exists for. Age and sex-based guidelines aim for the point where the balance tips in your favour."]},{"heading":"For women","paragraphs":["Cervical screening from the mid-20s, repeated every few years, catches changes caused by HPV years before they could become cancer, one of the most preventable cancers in existence when screening is kept up. Breast screening becomes relevant from 40, or earlier with a family history; know your own normal well enough to notice a change between screens too."]},{"heading":"For men","paragraphs":["Prostate screening (a PSA blood test) becomes a conversation from 45, informed rather than automatic, because the test itself has trade-offs a doctor should walk you through, not a default add-on to every checkup. Family history moves that conversation earlier."]},{"heading":"For everyone from 45","paragraphs":["Colorectal screening is worth discussing from 45, or earlier with a family history or persistent symptoms like unexplained bleeding or a change in bowel habit that lasts more than a couple of weeks. None of these tests are pleasant to think about, which is exactly why they''re worth booking on a schedule rather than waiting for a reason to feel ready."]}]'::jsonb, true, 61),
('hiv-hepatitis-screening-why-test', 'HIV and hepatitis screening: why testing beats guessing', 'How common undiagnosed infection actually is, why symptoms are a poor guide, and what a positive result actually means today.', 'Screening', 4, '/prevention', 'Preventive care at Tarragon', '[{"heading":"Why these three deserve their own conversation","paragraphs":["HIV, Hepatitis B and Hepatitis C can each be carried for years with no symptoms at all, quietly, while doing real damage in the background. Nigeria carries a significant share of both HIV and chronic Hepatitis B in the region, and a large share of people living with either don''t yet know it. Testing, not guessing from how you feel, is the only way to actually know."]},{"heading":"Who should test, honestly","paragraphs":["Everyone benefits from knowing their status at least once; it is not a test reserved for people who feel at risk. Pregnancy, a new relationship, a family member''s diagnosis, or simply never having been tested are all reasonable, unremarkable reasons to book it. A test result stays private between you and your care team."]},{"heading":"What a positive result actually means today","paragraphs":["HIV managed with modern treatment allows a long, normal life, and consistent treatment brings the virus low enough that it cannot be transmitted to a partner. Hepatitis B is managed with monitoring and, when needed, medication that controls it for decades. Neither diagnosis today looks like it did a generation ago; the earlier it''s found, the simpler that management is."]},{"heading":"The test itself","paragraphs":["A simple blood test at any decent lab, results usually back within days, sometimes the same day for HIV. There is nothing to prepare, and no reason to wait for a symptom that, for these three conditions, may never clearly arrive on its own."]}]'::jsonb, true, 62),
('adult-vaccines-you-might-be-missing', 'Vaccines aren''t just for children: what adults need too', 'The boosters and catch-up doses adults quietly miss, and why ''I had that as a child'' isn''t always the end of the story.', 'Screening', 4, '/prevention', 'Preventive care at Tarragon', '[{"heading":"Immunity doesn''t always last forever","paragraphs":["Some childhood vaccines wane over decades and need a booster in adulthood to stay effective; tetanus is the clearest example, needing a top-up roughly every ten years, a detail most adults have never been told. A vaccination record kept from childhood through adulthood, not two separate untracked histories, is what actually lets a doctor spot a gap."]},{"heading":"HPV catch-up, for women who missed it","paragraphs":["HPV vaccination is free at government primary health centres for girls aged 9 to 14 in Nigeria, but women who missed that window aren''t out of options: catch-up doses are bookable up to age 45 and still meaningfully lower the risk of the cancers HPV causes, including cervical cancer."]},{"heading":"Hepatitis B, if your series was never completed","paragraphs":["The Hepatitis B vaccine is a series of doses, not a single shot, and an incomplete series (a common gap when doses were given at different clinics with no shared record) doesn''t give full protection. If you''re not certain your series was completed, that''s worth confirming rather than assuming."]},{"heading":"Before travel, or before a pregnancy","paragraphs":["Travel to certain regions can require yellow fever proof or recommend typhoid coverage; planning a pregnancy is a good moment to confirm rubella immunity in particular, since infection during pregnancy carries real risk to the baby. Both are worth a conversation well before the trip or the pregnancy, not the week before."]}]'::jsonb, true, 63),
('blood-group-genotype-explained', 'Blood group and genotype: what they are, and why every Nigerian should know theirs', 'The difference between the two tests, why genotype matters especially before marriage or pregnancy, and how to actually get tested.', 'Screening', 4, '/prevention', 'Preventive care at Tarragon', '[{"heading":"Two different tests, often confused","paragraphs":["Blood group (A, B, AB or O, plus rhesus positive or negative) determines whose blood you can safely receive in a transfusion or emergency. Genotype (AA, AS, SS and rarer combinations) reveals whether you carry the gene for sickle cell disease. They answer completely different questions, and knowing one tells you nothing about the other."]},{"heading":"Why genotype matters so much here","paragraphs":["Nigeria carries one of the highest rates of the sickle cell gene in the world; a large share of the population carries AS (the trait, generally healthy) without knowing it. Two AS carriers having a child together have a 1-in-4 chance, each pregnancy, of a child with SS, sickle cell disease. Knowing your genotype before marriage or pregnancy turns that into an informed choice rather than a discovery after the fact."]},{"heading":"Carrying the trait isn''t the same as having the disease","paragraphs":["AS (sickle cell trait) is not sickle cell disease; most people who carry it live entirely normal lives with no symptoms. It only becomes a serious consideration for the children of two AS (or one AS, one SS) parents. Discovering you''re AS is information for family planning, not a diagnosis to be alarmed by."]},{"heading":"How to actually get tested","paragraphs":["Both are simple blood tests at any decent laboratory, results typically back within a day, no special preparation needed. If you''ve never checked either, or you''re planning a marriage or pregnancy and don''t have a written result you trust, it is one of the cheapest, most consequential pieces of information you can gather about your family''s future."]}]'::jsonb, true, 64),
('statins-myths-explained', 'Statins: what they actually do, and the myths that stop people taking them', 'Why statins are one of medicine''s most proven drugs, and an honest look at the side-effect fears that keep people from starting or staying on them.', 'Cholesterol', 4, '/chronic-care', 'Chronic care at Tarragon', '[{"heading":"What a statin actually does","paragraphs":["A statin lowers LDL cholesterol by slowing how much your liver makes, rather than by removing what''s already stuck in your arteries. Taken consistently, it measurably lowers the risk of heart attack and stroke in people whose overall cardiovascular risk is high enough to warrant it, one of the largest, most repeated findings in modern medicine."]},{"heading":"\"But I heard it damages your liver\"","paragraphs":["Serious liver injury from statins is rare; most people never need to stop for it, which is why a doctor checks liver function before starting and periodically after, not because harm is expected, but because checking is cheap and reassuring. Weigh that small, monitored risk against an unmonitored heart attack."]},{"heading":"Muscle aches: real, but often over-blamed","paragraphs":["Muscle aches are the complaint people raise most, and they are real for some people. But controlled studies that compare a statin against a fake pill find most reported muscle pain happens on the fake pill too, meaning expectation plays a large role. If aches do appear, a doctor can usually solve it by switching statins or adjusting dose rather than stopping treatment altogether."]},{"heading":"The actual risk of not taking it","paragraphs":["For someone whose doctor has assessed real cardiovascular risk and recommended a statin, stopping it quietly, without a conversation, removes one of the best-proven protections against a heart attack or stroke you can have. If side effects are genuinely bothering you, that is a reason to call your doctor, not to simply stop; there is almost always another option."]}]'::jsonb, true, 71)
